@preconcurrency import SwiftNumber
@preconcurrency import Eth
import Foundation

public enum CometSupplyMultipleAssetsAndBorrow {
    public static let creationCode: Hex = ""
    public static let runtimeCode: Hex = ""

    public static let InvalidInputError = ABI.Function(
            name: "InvalidInput",
            inputs: []
    )


    public enum RevertReason : Equatable, Error {
        case invalidInput
        case unknownRevert(String, String)
    }
    public static func rewrapError(_ error: ABI.Function, value: ABI.Value) -> RevertReason {
        switch (error, value) {
        case (InvalidInputError, _):
            return .invalidInput
        case let (e, v):
            return .unknownRevert(e.name, String(describing: v))
        }
    }
    public static let errors: [ABI.Function] = [InvalidInputError]
    public static let functions: [ABI.Function] = [runFn]
    public static let runFn = ABI.Function(
            name: "run",
            inputs: [.address, .array(.address), .array(.uint256), .address, .uint256, .array(.bool)],
            outputs: []
    )

    public static func run(comet: EthAddress, assets: [EthAddress], amounts: [Number], baseAsset: EthAddress, borrow: Number, cappedMaxes: [Bool], withFunctions ffis: EVM.FFIMap = [:]) throws -> Result<(), RevertReason> {
            do {
                let query = try runFn.encoded(with: [.address(comet), .array(.address, assets.map {
                                    .address($0)
                                }), .array(.uint256, amounts.map {
                                    .uint256($0)
                                }), .address(baseAsset), .uint256(borrow), .array(.bool, cappedMaxes.map {
                                    .bool($0)
                                })])
                let result = try EVM.runQuery(bytecode: runtimeCode, query: query, withErrors: errors, withFunctions: ffis)
                let decoded = try runFn.decode(output: result)

                switch decoded {
                case  .tuple0:
                    return .success(())
                default:
                    throw ABI.DecodeError.mismatchedType(decoded.schema, runFn.outputTuple)
                }
            } catch let EVM.QueryError.error(e, v) {
                return .failure(rewrapError(e, value: v))
            }
    }


    public static func runDecode(input: Hex) throws -> (EthAddress, [EthAddress], [Number], EthAddress, Number, [Bool]) {
        let decodedInput = try runFn.decodeInput(input: input)
        switch decodedInput {
        case let .tuple6(.address(comet), .array(.address, assets), .array(.uint256, amounts), .address(baseAsset), .uint256(borrow), .array(.bool, cappedMaxes)):
            return  (comet, assets.map { $0.asEthAddress! }, amounts.map { $0.asNumber! }, baseAsset, borrow, cappedMaxes.map { $0.asBool! })
        default:
            throw ABI.DecodeError.mismatchedType(decodedInput.schema, runFn.inputTuple)
        }
    }

}